input.command:
cat > /tmp/carlisted.sql <<'EOF'
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
-- distinct listed ids (exclude null)
CREATE OR REPLACE TABLE list_ids AS
SELECT DISTINCT cod_imovel FROM raw_list WHERE cod_imovel IS NOT NULL AND cod_imovel<>'';
-- pull all CAR rows for these ids, keep geometry as WKB->store as GEOMETRY
CREATE OR REPLACE TABLE car_listed AS
SELECT cod_imovel, mod_fiscal, num_area, municipio, cod_estado, geometry
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
WHERE cod_imovel IN (SELECT cod_imovel FROM list_ids);
.mode csv
SELECT '--- n distinct listed ids ---';
SELECT count(*) FROM list_ids;
SELECT '--- car_listed rows / distinct ids found ---';
SELECT count(*) rows, count(distinct cod_imovel) ids FROM car_listed;
SELECT '--- ids with >1 car row ---';
SELECT count(*) FROM (SELECT cod_imovel FROM car_listed GROUP BY 1 HAVING count(*)>1);
SELECT '--- missing ids (listed not in car) ---';
SELECT count(*) FROM list_ids WHERE cod_imovel NOT IN (SELECT cod_imovel FROM car_listed);
EOF
timeout 600 duckdb /workspace/work.db < /tmp/carlisted.sql 2>&1

