cat > /tmp/resolve_geom.sql <<'EOF'
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
.mode csv
SET VARIABLE carurl = 'https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet';

-- rowid 6 POINT (original orientation)
SELECT '--- r6 point orig ---';
SELECT cod_imovel, municipio, num_area FROM read_parquet(getvariable('carurl'))
WHERE bbox.xmin<=-51.39127228109898 AND bbox.xmax>=-51.39127228109898
  AND bbox.ymin<=-15.539711049431583 AND bbox.ymax>=-15.539711049431583
  AND ST_Contains(geometry, ST_Point(-51.39127228109898,-15.539711049431583));

-- rowid 118 POINT orig (-35,-10) and flipped (-10,-35)
SELECT '--- r118 point orig ---';
SELECT count(*) FROM read_parquet(getvariable('carurl'))
WHERE bbox.xmin<=-35 AND bbox.xmax>=-35 AND bbox.ymin<=-10 AND bbox.ymax>=-10
  AND ST_Contains(geometry, ST_Point(-35,-10));
SELECT '--- r118 point flipped ---';
SELECT count(*) FROM read_parquet(getvariable('carurl'))
WHERE bbox.xmin<=-10 AND bbox.xmax>=-10 AND bbox.ymin<=-35 AND bbox.ymax>=-35
  AND ST_Contains(geometry, ST_Point(-10,-35));
EOF
timeout 500 duckdb /workspace/work.db < /tmp/resolve_geom.sql 2>&1

