cat > /tmp/fieldmatch.sql <<'EOF'
LOAD spatial;
SET geometry_always_xy = true;
.mode csv

-- aggregate (union) fraction per field
CREATE OR REPLACE TABLE aggf AS
SELECT f.field_id, ST_Area(ST_Intersection(f.geometry,b.g))/a.farea4326 AS agg_frac
FROM fields f, bufunion b JOIN farea a ON a.field_id=f.field_id
WHERE ST_Intersects(f.geometry,b.g);

-- per-field single stats + primary cadaster
CREATE OR REPLACE TABLE single_stats AS
WITH s AS (SELECT field_id, cod_imovel, inter/farea4326 AS frac FROM fp)
SELECT field_id,
  max(frac) AS max_single_frac,
  (SELECT min(cod_imovel) FROM s s2 WHERE s2.field_id=s.field_id AND s2.frac >= (SELECT max(frac) FROM s s3 WHERE s3.field_id=s.field_id)-1e-9) AS primary_cod
FROM s GROUP BY field_id;

-- unified per-field match table
CREATE OR REPLACE TABLE field_match AS
SELECT f.field_id, f.mbmode24,
  COALESCE(ss.max_single_frac,0) AS max_single_frac,
  ss.primary_cod,
  COALESCE(ag.agg_frac,0) AS agg_frac,
  (COALESCE(ss.max_single_frac,0) >= 0.667) AS by_single,
  (COALESCE(ag.agg_frac,0) >= 0.667) AS by_agg,
  ((COALESCE(ss.max_single_frac,0) >= 0.667) OR (COALESCE(ag.agg_frac,0) >= 0.667)) AS matched,
  (f.field_id IN (SELECT field_id FROM fp)) AS touches_parcel,
  ST_Area(ST_Transform(f.geometry,'EPSG:4326','EPSG:5880'))/10000.0 AS field_area_ha,
  f.deforestarea0104/10000.0 AS l0104, f.deforestarea0509/10000.0 AS l0509,
  f.deforestarea1014/10000.0 AS l1014, f.deforestarea1520/10000.0 AS l1520,
  f.deforestarea2124/10000.0 AS l2124
FROM fields f
LEFT JOIN single_stats ss ON ss.field_id=f.field_id
LEFT JOIN aggf ag ON ag.field_id=f.field_id;

SELECT '--- q09 matched ---';   SELECT count(*) FILTER (WHERE matched) FROM field_match;
SELECT '--- q10 single / agg-only ---';
SELECT count(*) FILTER (WHERE by_single) by_single,
       count(*) FILTER (WHERE matched AND NOT by_single) by_agg_only FROM field_match;
SELECT '--- q12 excluded (touch positive area, fail both) ---';
SELECT count(*) FILTER (WHERE touches_parcel AND NOT matched) FROM field_match;
SELECT '--- q11 fractions over matched ---';
SELECT min(max_single_frac) min_single, avg(max_single_frac) avg_single, avg(agg_frac) avg_union
FROM field_match WHERE matched;
SELECT '--- q14 matched ha ---';
SELECT sum(field_area_ha) FROM field_match WHERE matched;
EOF
